// Platzhalter fuer das Werbe-SDK (GameDistribution): keine Werbung, keine Tracker.
(function () {
  function ev(n) { try { window.GD_OPTIONS && window.GD_OPTIONS.onEvent && window.GD_OPTIONS.onEvent({ name: n }); } catch (e) {} }
  window.gdsdk = {
    showBanner: function () { setTimeout(function () { ev("SDK_GAME_START"); }, 0); },
    play: function () {}, customLog: function () {},
    showAd: function () { setTimeout(function () { ev("SDK_GAME_START"); }, 0); return Promise.resolve(); },
    preloadAd: function () { return Promise.resolve(); }
  };
  setTimeout(function () { ev("SDK_READY"); ev("SDK_GAME_START"); }, 50);
})();
